-- Smart Colors integration for the Lua entrypoint.
-- GENERATED by the config generate-appearance.py from hornero-signal-night (schema v2);
-- do not hand-edit. Signal borders: 1 px matte, amber = active window.
-- luacheck: globals hl

local factory = {
	general = {
		col = {
			active_border = "rgba(f2a33aee)",
			inactive_border = "rgba(2c333ccc)",
		},
	},
	group = {
		col = {
			border_active = "rgba(f2a33aee)",
			border_inactive = "rgba(707a85aa)",
			border_locked_active = "rgba(7ec1eaee)",
			border_locked_inactive = "rgba(16303faa)",
		},
		groupbar = {
			col = {
				active = "rgba(f2a33aee)",
				inactive = "rgba(1f252eee)",
				locked_active = "rgba(7ec1eaee)",
				locked_inactive = "rgba(16303fee)",
			},
		},
	},
	decoration = {
		shadow = {
			color = "rgba(00000059)",
		},
	},
}

hl.config(factory)

local cache = os.getenv("HORNERO_SMART_COLORS_DIR")
if not cache or cache == "" then
	local cache_home = os.getenv("XDG_CACHE_HOME")
	if not cache_home or cache_home == "" then
		cache_home = (os.getenv("HOME") or "") .. "/.cache"
	end
	cache = cache_home .. "/hornero/smart-colors"
end

-- Applying a theme renders colors-hyprland.lua from the theme's roles
-- (lib/hornero/signal_render.py). Load it on every evaluation instead of
-- through require's cache so a reload picks up the new theme; a missing
-- or malformed file leaves the factory palette above in effect.
local generated = loadfile(cache .. "/colors-hyprland.lua")
if generated then
	pcall(generated)
end
